# ---------------------------------------------------------------------------
# Merge and split
#
# merge_metrics gathers several independent log sets into one set in a fixed
# order; split_metrics divides one set at caller-given record boundaries.
# Records move byte for byte with their original newlines, the copy streams
# with bounded memory, and every involved path is guarded and locked one
# after another in lexicographic path order (the same reentrant per-path
# guards and flock anchors the transaction commit uses), so same-process
# interleaving neither self-locks nor reports a spurious locking failure and
# two overlapping layout operations cannot deadlock.
#
# One JSON layout plan (``path.layout``) is published, byte identical, at
# every involved path -- the single commit point -- and each destination's
# whole replacement segment is staged at ``path.layoutstage``; while the
# marker and the stage coexist the stage alone is the readable member, just
# like compaction's ``path.compact``.  A crash leaves either the old sets or
# the finished layout, and a later write on any involved path settles the
# leftover plan idempotently (``_finish_staged_layout`` from
# ``_finish_pending``).  A stray stage with no plan is discarded.
#
# Ordinal mapping (all integers exact, never float):
#
# * Merge concatenates surviving record spans: span 0 is the destination's
#   own pre-operation span (kept verbatim when the destination exists),
#   then each source span in argument order with every pruned gap
#   compressed.  For span j, offset j shifts old write serials onto new
#   ones: new serial = old serial + offset; the offsets and the new pruned
#   basis are returned, so every destination record's new serial is
#   uniquely computable.
# * Split keeps the global ordinals: piece i starts at boundary i (piece 0
#   at the source's pruned basis), so a moved record keeps the exact serial
#   it had on the source.  A split boundary must land between records.
#
# Coordinator records are rewritten through the mapping (participating
# logs, per-log write intervals in the optional ``ranges`` field, exact
# decimal serials); already decided transactions keep their verdict, a
# still-live ``preparing`` begin rejects the operation (as it does at
# adjudication), and open prepared batches move their sidecar entries and
# stage bytes with their records.  Only coordinator records relevant to
# the involved logs are ever opened, so an unrelated corrupt record cannot
# disturb a merge or split.
# ---------------------------------------------------------------------------

_LAYOUT_STAMP_KEY = "l"
_LAYOUT_MOVED_KEY = "lm"


def _layout_doc_v1(document):
    """Validate one layout plan document; ``None`` for the done marker."""
    if not isinstance(document, dict):
        raise ValueError("corrupt layout plan: state must be a JSON object")
    if document.get("v") == 0 and set(document) == {"v"}:
        return None
    if document.get("v") != _LAYOUT_VERSION:
        raise ValueError("corrupt layout plan: bad version")
    required = {"v", "kind", "paths", "roles", "stamp"}
    if set(document) != required:
        raise ValueError("corrupt layout plan: unexpected fields")
    kind = document["kind"]
    if kind not in (_LAYOUT_KIND_MERGE, _LAYOUT_KIND_SPLIT):
        raise ValueError("corrupt layout plan: bad kind")
    paths = document["paths"]
    if not isinstance(paths, list) or not all(
        isinstance(one, str) for one in paths
    ) or len(set(paths)) != len(paths):
        raise ValueError("corrupt layout plan: bad path list")
    roles = document["roles"]
    if not isinstance(roles, dict) or set(roles) != set(paths):
        raise ValueError("corrupt layout plan: roles must match paths")
    for abspath, role in roles.items():
        if not isinstance(role, dict):
            raise ValueError("corrupt layout plan: bad role entry")
        if kind == _LAYOUT_KIND_MERGE:
            if set(role) != {"dest", "pruned"}:
                raise ValueError("corrupt layout plan: bad merge role")
        else:
            if set(role) != {"piece", "pruned"}:
                raise ValueError("corrupt layout plan: bad split role")
        if "dest" in role and not isinstance(role["dest"], bool):
            raise ValueError("corrupt layout plan: dest flag must be bool")
        if "piece" in role and (
            isinstance(role["piece"], bool)
            or not isinstance(role["piece"], int)
            or role["piece"] < -1
        ):
            raise ValueError("corrupt layout plan: bad piece index")
        if isinstance(role["pruned"], bool) or not isinstance(
            role["pruned"], int
        ) or role["pruned"] < 0:
            raise ValueError("corrupt layout plan: pruned must be a nonnegative int")
    if not isinstance(document["stamp"], str) or not document["stamp"]:
        raise ValueError("corrupt layout plan: bad stamp")
    return document


def _layout_read_raw(path):
    """Parse the layout marker if present; ``None`` when absent."""
    target = path + _LAYOUT_MARKER_SUFFIX
    try:
        fd = os.open(target, os.O_RDONLY)
    except FileNotFoundError:
        return None
    try:
        raw = b""
        while True:
            chunk = os.read(fd, _READ_CHUNK)
            if not chunk:
                break
            raw += chunk
    finally:
        os.close(fd)
    return json.loads(raw.decode("utf-8"))


def _layout_read(path):
    """Read and fully validate the layout marker at ``path``."""
    document = _layout_read_raw(path)
    if document is None:
        return None
    return _layout_doc_v1(document)


def _layout_write_marker(path, payload):
    """Atomically publish the layout marker, staged, fsynced and renamed."""
    _tx_publish_json(
        path + _LAYOUT_MARKER_TMP_SUFFIX,
        path + _LAYOUT_MARKER_SUFFIX,
        payload,
    )


def _layout_discard_local(path):
    """Remove every layout sidecar of an aborted, never-committed attempt."""
    for suffix in (
        _LAYOUT_MARKER_TMP_SUFFIX,
        _LAYOUT_STAGE_TMP_SUFFIX,
        _LAYOUT_STAGE_SUFFIX,
    ):
        _unlink_if_exists(path + suffix)


def _layout_retire_marker(path):
    """Retire the finished plan marker: trivial done doc then unlink."""
    try:
        _tx_publish_json(
            path + _LAYOUT_MARKER_TMP_SUFFIX,
            path + _LAYOUT_MARKER_SUFFIX,
            b'{"v":0}',
        )
    except OSError:
        return
    _unlink_if_exists(path + _LAYOUT_MARKER_SUFFIX)
    _unlink_if_exists(path + _LAYOUT_MARKER_TMP_SUFFIX)


def _layout_stage_out(tmp_path, records_iter):
    """Stream records into a private whole-segment temp, fsynced and closed."""
    out = os.open(tmp_path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
    count = 0
    try:
        for raw in records_iter:
            _write_bytes(out, raw)
            count += 1
        os.fsync(out)
    finally:
        os.close(out)
    return count


def _layout_promote(path):
    """Replace the set with its staged whole segment, compaction-style."""
    stage = path + _LAYOUT_STAGE_SUFFIX
    if not os.path.exists(stage):
        return
    for number in _segment_numbers(path):
        os.unlink(f"{path}.{number}")
    _truncate_live_log(path)
    os.replace(stage, f"{path}.1")


def _layout_publish_basis(path, pruned):
    """Set the destination's pruned basis and retire old snapshot handles.

    A layout is a new record sequence whose ordinals follow the publicly
    returned mapping, so creation-time snapshot handles of the old layout
    do not address the new one: they are retired and their pinned copies
    removed by the same orphan sweep any write runs.  Consumer groups and
    caller-named cursors stay on disk; callers rebuild positions through
    the public mapping.
    """
    _replace_marker(path, str(int(pruned)))
    registry = _read_snapshot_registry(path)
    for handle in list(registry):
        _unlink_if_exists(path + _SNAP_COPY_SUFFIX + handle)
    _write_snapshot_registry(path, {})
    _finish_snapshot_orphans(path)


def _layout_remove_set(path):
    """Remove a source path's whole log set and log-owned sidecars."""
    for number in _segment_numbers(path):
        _unlink_if_exists(f"{path}.{number}")
    _unlink_if_exists(path)
    for suffix in (
        _PRUNE_SUFFIX, _PRUNE_TMP_SUFFIX, _TRIM_SUFFIX, _TRIM_TMP_SUFFIX,
        _COMPACT_SUFFIX,
        _REGISTRY_SUFFIX, _REGISTRY_TMP_SUFFIX,
        _AUDIT_SUFFIX, _AUDIT_TMP_SUFFIX,
        _TX_SIDECAR_SUFFIX, _TX_SIDECAR_TMP_SUFFIX,
        _GROUP_COMMIT_SUFFIX, _GROUP_COMMIT_TMP_SUFFIX, _GROUP_LOCK_SUFFIX,
    ):
        _unlink_if_exists(path + suffix)
    directory = os.path.dirname(path) or "."
    for prefix in (_SNAP_COPY_SUFFIX, ".snapshots"):
        pass
    try:
        names = os.listdir(directory)
    except FileNotFoundError:
        names = ()
    base = os.path.basename(path)
    for name in names:
        if name.startswith(base + _SNAP_COPY_SUFFIX) or name.startswith(
            base + _TX_STAGE_SUFFIX
        ) or name.startswith(base + _TX_STAGE_TMP_SUFFIX):
            _unlink_if_exists(os.path.join(directory, name))


def _finish_staged_layout(path):
    """Settle a merge/split plan published at ``path`` (writer lock held).

    Local-role work only -- one path's lock is held: a destination/piece
    promotes its staged segment and publishes its basis; a removed source
    disappears only when the plan's destination side is visibly committed
    (its marker or staged segment is present), otherwise the dead plan is
    discarded and the untouched source keeps serving.  Every step is
    idempotent, so a crash simply repeats it on the next write.
    """
    try:
        document = _layout_read_raw(path)
    except ValueError:
        # A marker another process is replacing or a genuinely corrupt
        # marker: leave it for the next locked settler rather than raising
        # inside an unrelated entry point's settle pass.
        return
    if document is None:
        _unlink_if_exists(path + _LAYOUT_STAGE_TMP_SUFFIX)
        _unlink_if_exists(path + _LAYOUT_STAGE_SUFFIX)
        return
    if isinstance(document, dict) and document.get("v") == 0:
        _layout_discard_local(path)
        _unlink_if_exists(path + _LAYOUT_MARKER_SUFFIX)
        return
    try:
        layout = _layout_doc_v1(document)
    except ValueError:
        return
    abspath = os.path.abspath(path)
    role = layout["roles"].get(abspath)
    if role is None:
        _layout_discard_local(path)
        return
    kind = layout["kind"]
    if kind == _LAYOUT_KIND_MERGE:
        if role["dest"]:
            if os.path.exists(path + _LAYOUT_STAGE_SUFFIX):
                _layout_promote(path)
            _layout_publish_basis(path, role["pruned"])
            _layout_retire_marker(path)
            _layout_discard_local(path)
            return
        dest = next(
            one for one, entry in layout["roles"].items() if entry["dest"]
        )
        dest_path = _abspath_to_path(path, abspath, dest, layout["paths"])
        committed = os.path.exists(dest_path + _LAYOUT_MARKER_SUFFIX) or os.path.exists(
            dest_path + _LAYOUT_STAGE_SUFFIX
        ) or os.path.exists(dest_path + ".1")
        if committed:
            _layout_remove_set(path)
            _layout_retire_marker(path)
            _layout_discard_local(path)
        # Destination not visibly committed yet: leave the source and its
        # marker untouched; the driving operation (or a retry) finishes it.
        return
    # Split.
    piece = role["piece"]
    if piece >= 0:
        if os.path.exists(path + _LAYOUT_STAGE_SUFFIX):
            _layout_promote(path)
        _layout_publish_basis(path, role["pruned"])
        _layout_retire_marker(path)
        _layout_discard_local(path)
        return
    # The split source is removed once every piece has been promoted.
    ready = True
    for other, entry in layout["roles"].items():
        if entry["piece"] < 0:
            continue
        other_path = _abspath_to_path(path, abspath, other, layout["paths"])
        if not (
            os.path.exists(other_path + _LAYOUT_MARKER_SUFFIX)
            or os.path.exists(other_path + ".1")
        ):
            ready = False
            break
    if ready:
        _layout_remove_set(path)
        _layout_retire_marker(path)
        _layout_discard_local(path)


def _abspath_to_path(reference_path, reference_abs, target_abs, paths):
    """Best-effort target path for a sibling absolute plan path.

    Plan paths are absolute; sibling sidecars are reached by their
    absolute paths directly.  The reference arguments are accepted for
    symmetry with the call sites.
    """
    return target_abs


def _layout_set_summary(path):
    """``(pruned_basis, surviving_record_count)`` of the settled set."""
    basis = _read_prune_state(path)[0]
    surviving = 0
    for member in _segment_members(path):
        for _ in _iter_raw_records(member):
            surviving += 1
    return basis, surviving


def _layout_raw_members(path):
    """Stream ``(raw_record_bytes)`` across a path's resolved members."""
    members, _pruned = _resolve_members(path)
    for member in members:
        yield from _iter_raw_file_records(member)


def _layout_check_paths(paths, need_existing):
    """Type/directory/existence validation for a layout path list."""
    for path, existing in zip(paths, need_existing):
        if not isinstance(path, str):
            raise OSError(
                f"log path must be a string, got {type(path).__name__}"
            )
        if os.path.isdir(path):
            raise IsADirectoryError(f"log path is a directory: {path!r}")
        if existing and not os.path.exists(path) and not _segment_numbers(path):
            raise FileNotFoundError(f"metrics log does not exist: {path!r}")


def _layout_guard_lock(abspath, create):
    """Acquire one path's in-process guard and writer lock, settled."""
    guard = _tx_log_guard(abspath)
    guard.__enter__()
    fd = None
    try:
        if not os.path.exists(abspath) and not _segment_numbers(abspath):
            if not create:
                raise FileNotFoundError(
                    f"metrics log does not exist: {abspath!r}"
                )
        fd = _mutation_lock(abspath, create=create)
        _finish_pending(abspath)
        fd = _relock_after_settle(fd, abspath, create=create)
        return guard, fd
    except BaseException:
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass
        guard.__exit__(None, None, None)
        raise


def _layout_acquire_all(paths, create_flags):
    """Guard and lock every involved path in lexicographic order.

    Acquisition is strictly ordered and each path's guard is reentrant
    per process, so overlapping layout operations and transactions form
    an acyclic wait graph and same-process interleaving never self-locks.
    """
    order = sorted(range(len(paths)), key=lambda i: paths[i])
    held = []
    try:
        for index in order:
            guard, fd = _layout_guard_lock(paths[index], create_flags[index])
            held.append((paths[index], guard, fd))
        return held
    except BaseException:
        for _abspath, guard, fd in reversed(held):
            if fd is not None:
                try:
                    os.close(fd)
                except OSError:
                    pass
            guard.__exit__(None, None, None)
        raise


def _layout_release_all(held):
    for _abspath, guard, fd in reversed(held):
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass
        guard.__exit__(None, None, None)


def _tx_registry_records(wanted=None):
    """Yield coordinator records, narrowed to ``wanted`` absolute logs.

    A record is opened only when its id appears in one of the wanted
    logs' sidecars or its raw bytes name one of the wanted paths, so an
    unrelated corrupt record never raises into an operation scoped to
    other logs.  ``wanted`` of ``None`` reads every record, as before.
    """
    try:
        names = os.listdir(_tx_registry_dir())
    except FileNotFoundError:
        return
    sidecar_txids = set()
    if wanted is not None:
        wanted = set(wanted)
        for abspath in wanted:
            try:
                sidecar_txids.update(
                    int(text) for text in _tx_read_sidecar(abspath)
                )
            except FileNotFoundError:
                pass
        needles = [abspath.encode("utf-8") for abspath in wanted]
    for name in sorted(names):
        if not name.endswith(".json"):
            continue
        stem = name[:-5]
        if not (stem.isascii() and stem.isdigit()):
            continue
        full = os.path.join(_tx_registry_dir(), name)
        if wanted is not None and int(stem) not in sidecar_txids:
            fd = os.open(full, os.O_RDONLY)
            try:
                raw = b""
                while True:
                    chunk = os.read(fd, _READ_CHUNK)
                    if not chunk:
                        break
                    raw += chunk
                    if any(needle in raw for needle in needles):
                        break
            finally:
                os.close(fd)
            if not any(needle in raw for needle in needles):
                continue
        record = _tx_read_coordinator(int(stem))
        if record is not None:
            yield record


def _tx_log_intervals(record, abspath):
    """All write intervals ``(start, count)`` of one log of a record."""
    index = record["logs"].index(abspath)
    if "ranges" in record:
        return [(int(s), int(c)) for s, c in record["ranges"][index]]
    return [(record["serials"][index], len(record["records"][index]))]


def _tx_intervals_overlap(first, second):
    """True when any interval of one side overlaps any of the other."""
    for a_start, a_count in first:
        for b_start, b_count in second:
            if _tx_ranges_overlap(a_start, a_count, b_start, b_count):
                return True
    return False


def _layout_collect_txns(abspaths):
    """Read every coordinator record relevant to the involved logs."""
    return {
        record["id"]: record
        for record in _tx_registry_records(wanted=set(abspaths))
    }


def _layout_check_no_preparing(records, involved):
    """Reject the layout while a participating begin is still preparing."""
    for txid, record in records.items():
        if record["s"] != _TX_STATUS_PREPARING:
            continue
        if involved.isdisjoint(record["logs"]):
            continue
        prep_fd = _tx_prepare_lock_try(txid)
        if prep_fd is None or prep_fd is False:
            raise ValueError(
                f"transaction {txid} is still being prepared; finish it "
                f"before a merge or split"
            )
        os.close(prep_fd)


def _layout_intervals_shift(intervals, offset):
    """Shift whole intervals by an integer offset."""
    return [[start + offset, count] for start, count in intervals]


def _layout_stamp_record(record, stamp, moved):
    """Publish a remapped coordinator record tagged with the plan stamp."""
    if record.get(_LAYOUT_STAMP_KEY) == stamp:
        return False
    record[_LAYOUT_STAMP_KEY] = stamp
    if moved:
        record[_LAYOUT_MOVED_KEY] = stamp
    _tx_write_coordinator(record)
    return True


def _layout_remap_merge_record(record, span_of, offset_of, dest_abs):
    """Remap one coordinator record through the merge span mapping."""
    grouped = {}
    order = []
    untouched = []
    for index, abspath in enumerate(record["logs"]):
        lines = record["records"][index]
        intervals = _tx_log_intervals(record, abspath)
        if abspath in span_of:
            span = span_of[abspath]
            offset = offset_of[abspath]
            if dest_abs not in grouped:
                grouped[dest_abs] = {"spans": {}}
                order.append(dest_abs)
            grouped[dest_abs]["spans"].setdefault(span, []).append(
                (lines, _layout_intervals_shift(intervals, offset))
            )
        else:
            untouched.append((abspath, lines, intervals))
    new_entries = []
    for dest, data in grouped.items():
        all_lines = []
        all_intervals = []
        for span in sorted(data["spans"]):
            for lines, intervals in data["spans"][span]:
                all_lines.extend(lines)
                all_intervals.extend(intervals)
        all_intervals.sort(key=lambda interval: interval[0])
        new_entries.append((dest, all_lines, all_intervals))
    new_entries.extend(untouched)
    new_entries.sort(key=lambda entry: entry[0])
    record = dict(record)
    record["logs"] = [abspath for abspath, _l, _i in new_entries]
    record["records"] = [lines for _a, lines, _i in new_entries]
    intervals_by_log = [intervals for _a, _l, intervals in new_entries]
    record["ranges"] = intervals_by_log
    record["serials"] = [
        min(start for start, count in intervals) if intervals else 0
        for intervals in intervals_by_log
    ]
    return record


def _layout_remap_split_record(record, source_abs, piece_at, piece_abs):
    """Remap one coordinator record through the split boundary mapping."""
    slices = {}
    untouched = []
    for index, abspath in enumerate(record["logs"]):
        lines = record["records"][index]
        intervals = _tx_log_intervals(record, abspath)
        if abspath != source_abs:
            untouched.append((abspath, list(lines), intervals))
            continue
        cursor = 0
        for start, count in intervals:
            for at in range(start, start + count):
                piece = piece_at(at)
                bucket = slices.setdefault(
                    piece, {"lines": [], "intervals": []}
                )
                bucket["lines"].append(lines[cursor])
                cursor += 1
            existing = None
            for interval in bucket_parts(slices):
                pass
            bucket = slices[piece]
            merged = bucket["intervals"]
            if merged and merged[-1][0] + merged[-1][1] == start:
                merged[-1][1] += count
            elif merged and any(s == start for s, _c in merged):
                pass
            else:
                merged.append([start, count])
    new_entries = []
    for piece in sorted(slices):
        data = slices[piece]
        data["intervals"].sort(key=lambda interval: interval[0])
        new_entries.append(
            (piece_abs[piece], data["lines"], data["intervals"])
        )
    new_entries.extend(untouched)
    new_entries.sort(key=lambda entry: entry[0])
    record = dict(record)
    record["logs"] = [abspath for abspath, _l, _i in new_entries]
    record["records"] = [lines for _a, lines, _i in new_entries]
    intervals_by_log = [intervals for _a, _l, intervals in new_entries]
    record["ranges"] = intervals_by_log
    record["serials"] = [
        min(start for start, count in intervals) if intervals else 0
        for intervals in intervals_by_log
    ]
    return record


def bucket_parts(slices):
    return []


def _layout_move_prepared_merge(record, spans_abs, dest_path, stamp):
    """Move one open transaction's sidecar entry and stage to the merge dest."""
    if record.get(_LAYOUT_MOVED_KEY) == stamp:
        return
    txid = record["id"]
    merged_lines = []
    stage_parts = []
    for abspath in spans_abs:
        registry = _tx_read_sidecar(abspath)
        entry = registry.get(str(txid))
        if entry is not None:
            merged_lines.extend(entry["r"])
        stage_path = _tx_stage_path(abspath, txid)
        if os.path.exists(stage_path):
            stage_parts.append(stage_path)
    if not merged_lines and not stage_parts:
        return
    payload = b""
    for stage_path in stage_parts:
        fd = os.open(stage_path, os.O_RDONLY)
        try:
            while True:
                chunk = os.read(fd, _READ_CHUNK)
                if not chunk:
                    break
                payload += chunk
        finally:
            os.close(fd)
    if not payload and merged_lines:
        payload = _tx_batch_payload(merged_lines)
    if payload:
        _tx_write_stage(dest_path, txid, payload)
    dest_registry = _tx_read_sidecar(dest_path)
    if merged_lines:
        dest_registry[str(txid)] = {"r": merged_lines}
    _tx_write_sidecar(dest_path, dest_registry)
    for abspath in spans_abs:
        registry = _tx_read_sidecar(abspath)
        if registry.pop(str(txid), None) is not None:
            _tx_write_sidecar(abspath, registry)
        _tx_remove_stage(abspath, txid)


def _layout_move_prepared_split(record, source_path, piece_paths, piece_at, stamp):
    """Split one open transaction's sidecar entry and stage into pieces."""
    if record.get(_LAYOUT_MOVED_KEY) == stamp:
        return
    txid = record["id"]
    source_registry = _tx_read_sidecar(source_path)
    entry = source_registry.get(str(txid))
    if entry is None and not os.path.exists(_tx_stage_path(source_path, txid)):
        return
    lines = entry["r"] if entry is not None else []
    payload = b""
    stage_path = _tx_stage_path(source_path, txid)
    if os.path.exists(stage_path):
        fd = os.open(stage_path, os.O_RDONLY)
        try:
            while True:
                chunk = os.read(fd, _READ_CHUNK)
                if not chunk:
                    break
                payload += chunk
        finally:
            os.close(fd)
    if not payload and lines:
        payload = _tx_batch_payload(lines)
    source_abs = os.path.abspath(source_path)
    intervals = None
    for index, abspath in enumerate(record["logs"]):
        if abspath == source_abs:
            intervals = record["ranges"][index]
    if intervals is None:
        return
    per_piece = {}
    cursor = 0
    for start, count in intervals:
        for at in range(start, start + count):
            per_piece.setdefault(piece_at(at), []).append(lines[cursor])
            cursor += 1
    # Re-slice the exact stage payload by complete lines instead: payload
    # is newline-joined canonical lines identical to the sidecar order.
    raw_lines = payload.splitlines(keepends=True)
    if len(raw_lines) == len(lines):
        per_piece = {}
        index = 0
        for start, count in intervals:
            for at in range(start, start + count):
                per_piece.setdefault(piece_at(at), []).append(raw_lines[index])
                index += 1
    for piece, chunks in per_piece.items():
        piece_path = piece_paths[piece]
        piece_payload = b"".join(chunks)
        if piece_payload:
            _tx_write_stage(piece_path, txid, piece_payload)
        registry = _tx_read_sidecar(piece_path)
        text_lines = [chunk[:-1].decode("utf-8") for chunk in chunks]
        registry[str(txid)] = {"r": text_lines}
        _tx_write_sidecar(piece_path, registry)
    registry = _tx_read_sidecar(source_path)
    registry.pop(str(txid), None)
    _tx_write_sidecar(source_path, registry)
    _tx_remove_stage(source_path, txid)


def merge_metrics(destination, sources):
    """Merge several independent log sets into one, in a fixed order.

    ``sources`` is a non-empty sequence of existing log paths and
    ``destination`` the single target log path; the destination may
    already exist (its surviving records become span 0, keeping their
    write serials and pruned-count basis) or be created fresh.  The
    source sets are concatenated after the destination span in argument
    order, each source's pruned gap compressed away, and every record is
    copied byte for byte with its original newline -- nothing is
    re-rendered, so ``-0.0``, oversized exact counters and key order are
    preserved and torn tails and blank lines follow the established read
    rules.  Sources are left without a log set afterwards.

    The copy streams record by record with bounded memory, and every
    involved path is guarded and locked one after another in
    lexicographic order through the same anchors transactions use, so
    concurrent appends, commits, rollbacks, adjudications and replays
    proceed without a torn record, a deadlock or a spurious locking
    failure.  The identical layout plan is the atomic commit point; a
    crash leaves either the old sets or the merged one, and the next
    write on any involved path settles the leftover plan.

    Transaction write intervals are remapped through the same offsets and
    decided verdicts are reproduced as recorded; still-undecided
    transactions keep their smallest-id-first rule on the new serials,
    rejected batches never take effect, and an open prepared transaction
    moves its staging state with its records.  A transaction that is
    still preparing rejects the merge with :class:`ValueError`.  Only
    transaction records relevant to the involved logs are read, so an
    unrelated corrupt record elsewhere does not affect it.

    Returns a mapping describing the deterministic serial mapping, with
    keys ``kind``, ``destination``, ``pruned``, ``count`` and ``spans``;
    each span gives its ``path``, ``span`` index, old pruned ``basis``,
    ``surviving`` record count and ``offset``, so each moved record's new
    serial is ``old serial + offset``.  Every number is an exact integer.

    Raises:
        TypeError: ``sources`` is not a sequence or an argument has the
            wrong type.
        ValueError: no source is given, a path repeats, the destination
            is also a source, the transaction state is corrupt, or a
            transaction is still preparing.
        FileNotFoundError: a source does not exist.
        IsADirectoryError: an involved path is a directory.
        OSError: a path is not a string or locking/writing fails.
    """
    if not isinstance(destination, str):
        raise OSError(
            f"destination path must be a string, got "
            f"{type(destination).__name__}"
        )
    if isinstance(sources, str) or not isinstance(sources, (list, tuple)):
        raise TypeError(
            f"sources must be a sequence of log paths, got "
            f"{type(sources).__name__}"
        )
    sources = list(sources)
    if not sources:
        raise ValueError("merge requires at least one source log")
    _layout_check_paths([destination] + sources, [False] + [True] * len(sources))
    dest_abs = os.path.abspath(destination)
    source_abs = [os.path.abspath(path) for path in sources]
    if len(set(source_abs)) != len(source_abs):
        raise ValueError("a merge source path is repeated")
    if dest_abs in source_abs:
        raise ValueError("the merge destination must not also be a source")

    all_abs = [dest_abs] + source_abs
    held = _layout_acquire_all(all_abs, [True] + [False] * len(source_abs))
    try:
        for abspath in all_abs:
            leftover = _layout_read(abspath)
            if leftover is not None:
                _finish_staged_layout(abspath)

        dest_exists = os.path.exists(destination) or bool(
            _segment_numbers(destination)
        )
        if dest_exists:
            basis0, surviving0 = _layout_set_summary(destination)
        else:
            basis0, surviving0 = 0, 0
        spans = [{"abspath": dest_abs, "span": 0, "basis": basis0,
                  "surviving": surviving0}]
        for position, abspath in enumerate(source_abs, start=1):
            basis, surviving = _layout_set_summary(abspath)
            spans.append(
                {"abspath": abspath, "span": position,
                 "basis": basis, "surviving": surviving}
            )
        # Span 0 keeps its ordinals; each later span compresses its
        # pruned gap and continues at the surviving frontier.
        frontier = basis0 + surviving0
        for span in spans:
            if span["span"] == 0:
                span["offset"] = 0
            else:
                span["offset"] = frontier - span["basis"]
                frontier += span["surviving"]
        new_basis = basis0
        total_new = frontier

        records = _layout_collect_txns(all_abs)
        _layout_check_no_preparing(records, set(all_abs))

        tmp = destination + _LAYOUT_STAGE_TMP_SUFFIX

        def _all_records():
            if dest_exists:
                yield from _layout_raw_members(destination)
            for abspath in source_abs:
                yield from _layout_raw_members(abspath)

        written = _layout_stage_out(tmp, _all_records())
        expected = sum(span["surviving"] for span in spans)
        if written != expected:
            _unlink_if_exists(tmp)
            raise ValueError(
                "corrupt log set: record count changed while merge was staging"
            )

        stamp = os.urandom(8).hex()
        roles = {dest_abs: {"dest": True, "pruned": new_basis}}
        for abspath in source_abs:
            roles[abspath] = {"dest": False, "pruned": 0}
        plan = {
            "v": _LAYOUT_VERSION,
            "kind": _LAYOUT_KIND_MERGE,
            "paths": sorted(all_abs),
            "roles": roles,
            "stamp": stamp,
        }
        payload = json.dumps(plan, separators=(",", ":")).encode("utf-8")

        # Rewrite the participating coordinators through the mapping
        # before the commit point; an untagged record is the pre-merge
        # form, so a crashed retry never shifts a serial twice.
        span_of = {span["abspath"]: span["span"] for span in spans}
        offset_of = {span["abspath"]: span["offset"] for span in spans}
        for record in records.values():
            new_record = _layout_remap_merge_record(
                record, span_of, offset_of, dest_abs
            )
            _layout_stamp_record(new_record, stamp, moved=True)

        # Single commit point: identical plan at every involved path.
        for abspath in all_abs:
            _layout_write_marker(abspath, payload)
        os.rename(tmp, destination + _LAYOUT_STAGE_SUFFIX)

        _layout_promote(destination)
        _layout_publish_basis(destination, new_basis)
        for record in records.values():
            if record["s"] == _TX_STATUS_PREPARED or record.get("a") == (
                _TX_VERDICT_WINNER
            ):
                _layout_move_prepared_merge(
                    record, all_abs, destination, stamp
                )
        _sync_audit_for_write(destination)
        for abspath in source_abs:
            _layout_remove_set(abspath)
        for abspath in all_abs:
            _layout_retire_marker(abspath)
            _layout_discard_local(abspath)

        return {
            "kind": _LAYOUT_KIND_MERGE,
            "destination": dest_abs,
            "pruned": new_basis,
            "count": total_new,
            "spans": [
                {
                    "path": span["abspath"],
                    "span": span["span"],
                    "basis": span["basis"],
                    "surviving": span["surviving"],
                    "offset": span["offset"],
                }
                for span in spans
            ],
        }
    finally:
        _layout_release_all(held)


def split_metrics(source, destinations, boundaries):
    """Split one log set at record boundaries into several sets.

    ``destinations`` names one or more target logs and ``boundaries`` the
    one-fewer strictly increasing write-serial cut points: piece 0
    receives records with serials from the source's pruned basis up to
    ``boundaries[0]``, piece i the records between ``boundaries[i-1]``
    and ``boundaries[i]``, and the last piece the remaining tail.  A
    boundary must name a whole-record boundary -- never the middle of a
    record -- and stay within the settled record total, otherwise
    :class:`ValueError` is raised before anything moves.  Pieces keep the
    global ordinals: piece i's pruned basis is its boundary, so every
    moved record keeps the exact serial it had on the source.  Empty
    pieces are produced as empty sets.  The source set is removed once
    every piece is published.

    Records are fanned out in one streamed pass, byte for byte with
    original newlines (``-0.0``, oversized counters and key order all
    preserved; torn tails and blank lines follow the read rules), with
    bounded memory regardless of set size.  Locking, crash staging,
    transaction remapping and registry narrowing all follow
    :func:`merge_metrics`.

    Returns the deterministic mapping with keys ``kind``, ``source``,
    ``pruned``, ``count`` and ``pieces``; each piece gives its ``path``,
    ``piece`` index, pruned ``basis`` (its first global serial) and
    ``surviving`` record count.

    Raises:
        TypeError: an argument has the wrong type (booleans do not count
            as integer boundaries).
        ValueError: no destination, boundary/piece count mismatch,
            negative, non-increasing or out-of-range boundaries, a
            repeated path, a source among the destinations, corrupt
            transaction state, or a still-preparing transaction.
        FileNotFoundError: the source does not exist.
        IsADirectoryError: an involved path is a directory.
        OSError: a path is not a string or locking/writing fails.
    """
    if not isinstance(source, str):
        raise OSError(
            f"source path must be a string, got {type(source).__name__}"
        )
    if isinstance(destinations, str) or not isinstance(
        destinations, (list, tuple)
    ):
        raise TypeError(
            f"destinations must be a sequence of log paths, got "
            f"{type(destinations).__name__}"
        )
    if isinstance(boundaries, str) or not isinstance(
        boundaries, (list, tuple)
    ):
        raise TypeError(
            f"boundaries must be a sequence of integers, got "
            f"{type(boundaries).__name__}"
        )
    destinations = list(destinations)
    boundaries = list(boundaries)
    if not destinations:
        raise ValueError("split requires at least one destination log")
    if len(boundaries) != len(destinations) - 1:
        raise ValueError(
            f"split needs one fewer boundary than destinations: "
            f"{len(destinations)} destination(s) but {len(boundaries)} "
            f"boundary/boundaries"
        )
    for boundary in boundaries:
        if isinstance(boundary, bool) or not isinstance(boundary, int):
            raise TypeError(
                f"split boundary must be an integer, got "
                f"{type(boundary).__name__}"
            )
        if boundary < 0:
            raise ValueError("split boundary must not be negative")
    _layout_check_paths(
        [source] + destinations, [True] + [False] * len(destinations)
    )
    source_abs = os.path.abspath(source)
    dest_abs = [os.path.abspath(path) for path in destinations]
    if len(set(dest_abs)) != len(dest_abs):
        raise ValueError("a split destination path is repeated")
    if source_abs in dest_abs:
        raise ValueError("a split destination must not also be the source")

    all_abs = [source_abs] + dest_abs
    held = _layout_acquire_all(all_abs, [False] + [True] * len(dest_abs))
    try:
        for abspath in all_abs:
            leftover = _layout_read(abspath)
            if leftover is not None:
                _finish_staged_layout(abspath)

        basis, surviving = _layout_set_summary(source)
        total = basis + surviving
        if boundaries and (
            boundaries[0] < basis or boundaries[-1] > total
        ):
            raise ValueError(
                f"split boundary outside the record range "
                f"[{basis}, {total}]"
            )
        for index in range(1, len(boundaries)):
            if boundaries[index] <= boundaries[index - 1]:
                raise ValueError(
                    "split boundaries must be strictly increasing record "
                    "boundaries"
                )
        piece_bases = [basis] + boundaries
        cuts = boundaries + [total]

        def _piece_at(ordinal):
            piece = 0
            while piece < len(cuts) and ordinal >= cuts[piece]:
                piece += 1
            return piece

        records = _layout_collect_txns(all_abs)
        _layout_check_no_preparing(records, set(all_abs))

        tmp_paths = [path + _LAYOUT_STAGE_TMP_SUFFIX for path in destinations]
        fds = [
            os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
            for tmp in tmp_paths
        ]
        written = [0] * len(destinations)
        try:
            ordinal = basis
            for raw in _layout_raw_members(source):
                piece = _piece_at(ordinal)
                _write_bytes(fds[piece], raw)
                written[piece] += 1
                ordinal += 1
            for fd in fds:
                os.fsync(fd)
        finally:
            for fd in fds:
                try:
                    os.close(fd)
                except OSError:
                    pass

        stamp = os.urandom(8).hex()
        roles = {source_abs: {"piece": -1, "pruned": basis}}
        for position, abspath in enumerate(dest_abs):
            roles[abspath] = {"piece": position, "pruned": piece_bases[position]}
        plan = {
            "v": _LAYOUT_VERSION,
            "kind": _LAYOUT_KIND_SPLIT,
            "paths": sorted(all_abs),
            "roles": roles,
            "stamp": stamp,
        }
        payload = json.dumps(plan, separators=(",", ":")).encode("utf-8")

        piece_abs = {position: abspath for position, abspath in enumerate(dest_abs)}
        for record in records.values():
            if source_abs in record["logs"]:
                new_record = _layout_remap_split_record(
                    record, source_abs, _piece_at, piece_abs
                )
                _layout_stamp_record(new_record, stamp, moved=True)

        for abspath in all_abs:
            _layout_write_marker(abspath, payload)
        for position, path in enumerate(destinations):
            os.rename(
                tmp_paths[position], path + _LAYOUT_STAGE_SUFFIX
            )
        for position, path in enumerate(destinations):
            _layout_promote(path)
            _layout_publish_basis(path, piece_bases[position])
        for record in records.values():
            if record["s"] == _TX_STATUS_PREPARED or record.get("a") == (
                _TX_VERDICT_WINNER
            ):
                if source_abs in record["logs"]:
                    _layout_move_prepared_split(
                        record, source, destinations, _piece_at, stamp
                    )
        _layout_remove_set(source)
        for abspath in all_abs:
            _layout_retire_marker(abspath)
            _layout_discard_local(abspath)

        return {
            "kind": _LAYOUT_KIND_SPLIT,
            "source": source_abs,
            "pruned": basis,
            "count": total,
            "pieces": [
                {
                    "path": dest_abs[position],
                    "piece": position,
                    "basis": piece_bases[position],
                    "surviving": written[position],
                }
                for position in range(len(destinations))
            ],
        }
    except BaseException:
        for tmp in tmp_paths:
            _unlink_if_exists(tmp)
        raise
    finally:
        _layout_release_all(held)
