def _tx_log_ranges(record, abspath):
    """All write-serial intervals of one log's participation.

    A classical transaction occupies one contiguous interval starting at
    its write serial; a coordinator record rewritten by a merge or split
    carries an explicit ``ranges`` field whose per-log value is a list of
    ``[start, count]`` intervals in ascending order (one logical batch may
    straddle a former span boundary).  Every count is an exact integer.
    """
    index = _tx_log_index(record, abspath)
    if "ranges" in record:
        return [[int(start), int(count)]
