def _tx_registry_records(wanted=None):
    """Yield coordinator records in the registry directory.

    A missing registry directory yields nothing; staging, lock and other
    sidecar names are skipped.  ``wanted`` is an optional iterable of
    absolute log paths: when given, only records that name one of those
    paths in their raw bytes or carry an entry in one of those logs'
    sidecars are opened and parsed, so a corrupt unrelated record cannot
    disturb an operation scoped to other logs (the read scope is narrowed
    to the logs of the current operation).  With ``wanted`` of ``None``
    every record is read, as before; a present but corrupt record that is
    in scope raises :class:`ValueError` exactly as
    :func:`_tx_read_coordinator` does.
    """
    try:
        names = os.listdir(_tx_registry_dir())
    except FileNotFoundError:
        return
    wanted_set = None if wanted is None else set(wanted)
    needles = None
    sidecar_txids = None
    if wanted_set is not None:
        needles = [abspath.encode("utf-8") for abspath in wanted_set]
        sidecar_txids = set()
        for abspath in wanted_set:
            try:
                sidecar_txids.update(
                    int(text) for text in _tx_read_sidecar(abspath)
                )
            except FileNotFoundError:
                pass
    for name in sorted(names):
        if not name.endswith(".json"):
