_layout_op_guard_table_lock = threading.Lock()
_layout_op_guards = {}
_layout_op_guard_refs = {}
_LAYOUT_OP_LOCK_SUFFIX = ".layoutop.lock"


def _layout_op_locks(all_abs):
    """Serialize overlapping layout operations via per-path anchor flocks.

    One anchor per involved path (``path.layoutop.lock``), taken in
    lexicographic order and all held for the operation, makes the combined
    acquisition graph acyclic for any two overlapping merges/splits and
    excludes a second layout that touches a shared path while one is in
    flight.  Ordinary appends never take these anchors, so a layout still
    does not block them; the per-path staging locks keep data access
    ordered.  Returns a list of ``(abspath, guard, fd)``.
    """
    held = []
    for abspath in sorted(all_abs):
        key = abspath + _LAYOUT_OP_LOCK_SUFFIX
        with _layout_op_guard_table_lock:
            guard = _layout_op_guards.get(key)
            if guard is None:
                guard = threading.RLock()
                _layout_op_guards[key] = guard
                _layout_op_guard_refs[key] = 0
            _layout_op_guard_refs[key] += 1
        guard.acquire()
        fd = None
        try:
            if fcntl is not None:
                descriptor = os.open(
                    abspath + _LAYOUT_OP_LOCK_SUFFIX,
                    os.O_RDWR | os.O_CREAT, 0o666,
                )
                try:
                    fcntl.flock(descriptor, fcntl.LOCK_EX)
                except OSError:
                    os.close(descriptor)
                    raise
                fd = descriptor
            held.append((abspath, guard, fd, key))
        except BaseException:
            if fd is not None:
                try:
                    os.close(fd)
                except OSError:
                    pass
            guard.release()
            with _layout_op_guard_table_lock:
                _layout_op_guard_refs[key] -= 1
                if _layout_op_guard_refs[key] == 0:
                    del _layout_op_guards[key]
                    del _layout_op_guard_refs[key]
            raise
    return held


