def merge_metrics(destination, sources):
    # The body and the full contract live on _merge_metrics_run; this
    # wrapper only serializes overlapping layouts (per-path anchor locks
    # in lexicographic order) and finishes any plan a crash left behind
    # before a new layout starts.
    if not isinstance(destination, str):
        return _merge_metrics_run(destination, sources)
    _layout_check_sequence(sources, "sources")
    sources = list(sources)
    all_abs = [os.path.abspath(destination)] + [
        os.path.abspath(one) for one in sources if isinstance(one, str)
    ]
    held = _layout_op_locks(sorted(set(all_abs)))
    try:
        _layout_barrier_paths(all_abs)
        return _merge_metrics_run(destination, sources)
    finally:
        _layout_op_unlocks(held)


merge_metrics.__doc__ = _merge_metrics_run.__doc__


def split_metrics(source, destinations, boundaries):
    # See merge_metrics: anchor locks serialize overlapping layouts and a
    # leftover plan is driven to completion before this one starts.
