_LAYOUT_OP_LOCK_SUFFIX = ".layoutop.lock"


def _layout_op_acquire_all(abspaths):
    """Acquire every involved path's shared per-log guard in sorted order."""
    held = []
    for abspath in sorted(set(abspaths)):
