def _layout_driver_dir():
    directory = os.path.join(tempfile.gettempdir(), "weighted_batcher_layout")
    os.makedirs(directory, exist_ok=True)
    return directory


def _layout_op_enter(abspath):
    """Acquire one path's operation anchor; returns an opaque held token."""
    key = abspath + _LAYOUT_OP_LOCK_SUFFIX
    with _layout_op_guard_table_lock:
        guard = _layout_op_guards.get(key)
        if guard is None:
            guard = threading.RLock()
            _layout_op_guards[key] = guard
            _layout_op_guard_refs[key] = 0
        _layout_op_guard_refs[key] += 1
    guard.acquire()
    fd = None
    if fcntl is not None:
        descriptor = os.open(abspath + _LAYOUT_OP_LOCK_SUFFIX,
                             os.O_RDWR | os.O_CREAT, 0o666)
        try:
            fcntl.flock(descriptor, fcntl.LOCK_EX)
        except OSError:
            os.close(descriptor)
            guard.release()
            with _layout_op_guard_table_lock:
                _layout_op_guard_refs[key] -= 1
                if _layout_op_guard_refs[key] == 0:
                    del _layout_op_guards[key]
                    del _layout_op_guard_refs[key]
            raise
        fd = descriptor
    return (key, guard, fd)


def _layout_op_exit(held):
    if held is None:
        return
    key, guard, fd = held
    if fd is not None:
        try:
            os.close(fd)
        except OSError:
            pass
    guard.release()
    with _layout_op_guard_table_lock:
        _layout_op_guard_refs[key] -= 1
        if _layout_op_guard_refs[key] == 0:
            del _layout_op_guards[key]
            del _layout_op_guard_refs[key]


def _layout_op_acquire_all(abspaths):
    """Acquire every involved anchor in lexicographic order."""
    held = []
    for abspath in sorted(set(abspaths)):
        held.append((abspath, _layout_op_enter(abspath)))
    return held


def _layout_op_release_all(held):
    for abspath, token in reversed(held):
